INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES ("アサヒ", "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", 1, 1, 6000, 2, "---", 0, 3, "");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES ("部員3", "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", 1, 3, 16000, 3, "アドレナリン", 3, 0, "ホームランを連発すると、連発数に応じてパワーアップする");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES ("{0}", "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", 1, 2, 30000, 4, "ラッキー", 2, 2, "幸運のハプニングを呼び込む");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES ("選手名鑑 おまけページ", "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", 0, 0, 50000, 5, "", 1, 1, "");
